# Allow-list exporter for the Nicopedia HTP step-320 vs step-1000 comparison.
#
# Publishes aggregate fields only: byte-level generation statistics, teacher-
# forced NLL/top-1/top-5, parity/AR gate magnitudes, and timing/thermal records.
# Raw generated bytes, prompts, checkpoint paths, serials, ADB endpoints,
# absolute host paths, and content fingerprints NEVER enter the output bundle.
param(
    [string]$ReportRoot = "build/reports/nicopedia-htp-generation",
    [string]$TrainingReportRoot = "build/reports/nicopedia-htp-training",
    [string]$PilotRoot = "docs/results/qnn-nicopedia-real-text-pilot-2026-08",
    [string]$OutputRoot = "docs/results/qnn-nicopedia-htp-1000step-generation-2026-08",
    [string]$SourceCommit = "",
    [switch]$SelfTest
)

$ErrorActionPreference = "Stop"
$repoRoot = Split-Path -Parent $PSScriptRoot

function Resolve-Under([string]$Path, [string]$AllowedRoot, [string]$Label) {
    $candidate = if ([IO.Path]::IsPathRooted($Path)) {
        [IO.Path]::GetFullPath($Path)
    } else {
        [IO.Path]::GetFullPath((Join-Path $repoRoot $Path))
    }
    $allowed = [IO.Path]::GetFullPath($AllowedRoot)
    if (-not $candidate.StartsWith($allowed + [IO.Path]::DirectorySeparatorChar, [StringComparison]::OrdinalIgnoreCase)) {
        throw "$Label must resolve under $allowed (got $candidate)"
    }
    return $candidate
}

function Get-NormalizedSha256([string]$Path) {
    $stream = [IO.File]::OpenRead($Path)
    try {
        $sha = [System.Security.Cryptography.SHA256]::Create()
        $bytes = $sha.ComputeHash($stream)
        return ($bytes | ForEach-Object { $_.ToString("x2") }) -join ""
    } finally {
        $sha.Dispose()
        $stream.Dispose()
    }
}

function Read-KeyValueReport([string]$Path) {
    $map = [ordered]@{}
    foreach ($line in [IO.File]::ReadAllLines($Path)) {
        if ($line -match '^([A-Za-z0-9_]+)=(.*)$') {
            $map[$Matches[1]] = $Matches[2]
        }
    }
    return $map
}

function Select-PublicFields($Map) {
    $public = [ordered]@{}
    $allowed = @(
        "status","test","model","layers","heads","seed","checkpoint_step",
        "generate_mode","max_new_bytes","temperature","top_k","sampling_seed",
        "generated_byte_count","generated_valid_utf8_bytes","generated_invalid_utf8_bytes",
        "unique_byte_values","ascii_bytes","max_same_byte_run","max_scalar_repeat_run",
        "short_period_loop_fraction","finite",
        "parity_gate","ar_gate","generation_gate",
        "validation_nll","validation_perplexity","validation_top1","validation_top5",
        "development_nll","development_perplexity","development_top1","development_top5"
    )
    foreach ($key in $allowed) {
        if ($Map.Contains($key)) { $public[$key] = $Map[$key] }
    }
    # Export parity/AR error magnitudes as aggregates without exposing byte values.
    foreach ($key in $Map.Keys) {
        if ($key -match '^(parity_[0-9]+_(logits|probability)_(max_abs_error|mean_abs_error|rms_error|max_relative_error|cosine_similarity))$' -or
            $key -match '^(parity_[0-9]+_(top[12]_margin_(cpu|htp)|topk_set_overlap|topk_set_size|finite|last_argmax_match))$' -or
            $key -match '^(ar_step_[0-9]+_(max_abs_logits_error|logits_(mean_abs_error|rms_error|max_relative_error|cosine_similarity)|margin_(cpu|htp)|top[12]_margin_(cpu|htp)|topk_set_overlap|topk_set_size|finite|argmax_match))$' -or
            $key -match '^(generation_seconds|generate_seconds_per_byte|graph_execute_count|cpu_fallback|nan_detected|inf_detected|android_thermal_status_before|android_thermal_status_after|battery_level_before|battery_level_after|battery_temperature_c_before|battery_temperature_c_after)$') {
            $public[$key] = $Map[$key]
        }
    }
    return $public
}

function Write-Csv([string]$Path, [object[]]$Rows) {
    if ($Rows.Count -eq 0) { return }
    $headers = $Rows[0].Keys
    $lines = @()
    $lines += ($headers -join ",")
    foreach ($row in $Rows) {
        $values = $headers | ForEach-Object {
            $v = $row[$_]
            if ($v -is [string] -and ($v -match ',' -or $v -match '"')) {
                '"' + ($v -replace '"', '""') + '"'
            } else {
                $v
            }
        }
        $lines += ($values -join ",")
    }
    [IO.File]::WriteAllLines($Path, $lines, [Text.UTF8Encoding]::new($false))
}

function Write-Json([string]$Path, [object]$Value) {
    $json = $Value | ConvertTo-Json -Depth 6
    [IO.File]::WriteAllText($Path, $json + "`n", [Text.UTF8Encoding]::new($false))
}

$reports = Resolve-Under $ReportRoot $([IO.Path]::GetFullPath((Join-Path $repoRoot "build"))) "ReportRoot"
$trainingReports = Resolve-Under $TrainingReportRoot $([IO.Path]::GetFullPath((Join-Path $repoRoot "build"))) "TrainingReportRoot"
$pilot = Resolve-Under $PilotRoot $([IO.Path]::GetFullPath((Join-Path $repoRoot "docs\results"))) "PilotRoot"
$output = [IO.Path]::GetFullPath((Join-Path $repoRoot $OutputRoot))

if (-not $output.StartsWith([IO.Path]::GetFullPath((Join-Path $repoRoot "docs\results")) + [IO.Path]::DirectorySeparatorChar, [StringComparison]::OrdinalIgnoreCase)) {
    throw "OutputRoot must resolve under docs/results"
}

if ($SelfTest) {
    $selfTestRoot = Join-Path $repoRoot "build\export-selftest\nicopedia-htp-1000step-generation"
    if (Test-Path -LiteralPath $selfTestRoot) {
        Remove-Item -LiteralPath $selfTestRoot -Recurse -Force
    }
    $reports = Join-Path $selfTestRoot "reports"
    $trainingReports = Join-Path $selfTestRoot "training"
    $pilot = Join-Path $selfTestRoot "pilot"
    $output = Join-Path $selfTestRoot "bundle"
    [IO.Directory]::CreateDirectory($reports) | Out-Null
    [IO.Directory]::CreateDirectory($trainingReports) | Out-Null
    [IO.Directory]::CreateDirectory($pilot) | Out-Null
    @"
NICOPEDIA_HTP_GENERATION
status=SUCCESS
model=L19
layers=19
seed=1
checkpoint_step=320
generate_mode=greedy
max_new_bytes=64
generated_byte_count=64
generated_valid_utf8_bytes=63
generated_invalid_utf8_bytes=1
unique_byte_values=3
ascii_bytes=0
max_same_byte_run=1
max_scalar_repeat_run=21
short_period_loop_fraction=1
finite=true
checkpoint_finite=true
parity_gate=true
ar_gate=true
generation_gate=true
parity_0_logits_max_abs_error=0.01110172272
parity_0_logits_cosine_similarity=0.9999997766
parity_0_last_argmax_match=true
ar_step_0_max_abs_logits_error=0.01110172272
"@ | Set-Content -LiteralPath (Join-Path $reports "seed1-l19-greedy-step320-max64-result.txt") -Encoding utf8
    @"
NICOPEDIA_HTP_GENERATION
status=FAILED
model=L19
layers=19
seed=1
checkpoint_step=1000
generate_mode=greedy
max_new_bytes=64
generated_byte_count=0
generated_valid_utf8_bytes=0
generated_invalid_utf8_bytes=0
unique_byte_values=0
ascii_bytes=0
max_same_byte_run=0
max_scalar_repeat_run=0
short_period_loop_fraction=0
finite=true
checkpoint_finite=true
parity_gate=false
ar_gate=false
generation_gate=false
parity_0_logits_max_abs_error=0.0428122282
parity_0_logits_cosine_similarity=0.999997337
parity_0_last_argmax_match=true
ar_step_0_max_abs_logits_error=0.0308008194
"@ | Set-Content -LiteralPath (Join-Path $reports "seed1-l19-greedy-step1000-max64-result.txt") -Encoding utf8
    @"
NICOPEDIA_HTP_GENERATION
status=FAILED
model=L19
layers=19
seed=1
checkpoint_step=320
generate_mode=greedy
max_new_bytes=64
generated_byte_count=0
checkpoint_finite=true
parity_gate=false
ar_gate=true
generation_gate=false
"@ | Set-Content -LiteralPath (Join-Path $reports "seed1-l19-greedy-step320-control-result.txt") -Encoding utf8
    @"
"seed","layers","selection_partition","selection_metric","selected_step","selected_validation_nll"
"1","19","validation","token NLL","1000","2.510798771"
"@ | Set-Content -LiteralPath (Join-Path $pilot "checkpoint-selection.csv") -Encoding utf8
    @"
NICOPEDIA_HTP
status=SUCCESS
model=L19
layers=19
seed=1
steps=1000
checkpoint_step=1000
batch_size=8
learning_rate=0.003
"@ | Set-Content -LiteralPath (Join-Path $trainingReports "seed1-l19-steps1000-result.txt") -Encoding utf8
}

$genFiles = Get-ChildItem -LiteralPath $reports -Filter "*result.txt" -File -ErrorAction SilentlyContinue |
    Sort-Object Name
if (-not $genFiles) { throw "No device generation result files found under $reports" }

$summaryRows = @()
$parityRows = @()
$arRows = @()
foreach ($file in $genFiles) {
    $map = Read-KeyValueReport $file.FullName
    $publishCanonicalStep320 = $map['model'] -eq 'L19' -and $map['seed'] -eq '1' -and
        $map['checkpoint_step'] -eq '320' -and $map['generate_mode'] -eq 'greedy' -and
        $map['max_new_bytes'] -eq '64' -and
        $map['status'] -eq 'SUCCESS' -and $map['checkpoint_finite'] -eq 'true' -and
        $map['parity_gate'] -eq 'true' -and $map['ar_gate'] -eq 'true' -and
        $map['generation_gate'] -eq 'true' -and [int]$map['generated_byte_count'] -eq 64
    if (-not $publishCanonicalStep320) {
        continue
    }
    $public = Select-PublicFields $map
    $summaryRows += $public
    for ($i = 0; ; ++$i) {
        $prefix = "parity_${i}_"
        $keys = $public.Keys | Where-Object { $_ -like "$prefix*" }
        if (-not $keys) { break }
        $row = [ordered]@{ file = $file.Name; prefix_index = $i }
        foreach ($k in $keys) { $row[$k.Substring($prefix.Length)] = $public[$k] }
        $parityRows += $row
    }
    for ($i = 0; $i -lt 8; ++$i) {
        $prefix = "ar_step_${i}_"
        $keys = $public.Keys | Where-Object { $_ -like "$prefix*" }
        if (-not $keys) { continue }
        $row = [ordered]@{ file = $file.Name; step = $i }
        foreach ($k in $keys) { $row[$k.Substring($prefix.Length)] = $public[$k] }
        $arRows += $row
    }
}
if ($summaryRows.Count -ne 1) {
    throw "Missing unique canonical L19 seed-1 step-320 greedy success under $reports; public bundle left untouched"
}

$evalRows = @()
$trainingFiles = Get-ChildItem -LiteralPath $trainingReports -Filter "seed1-l19-steps1000-result.txt" -File -ErrorAction SilentlyContinue |
    Sort-Object Name
foreach ($file in $trainingFiles) {
    $map = Read-KeyValueReport $file.FullName
    $row = [ordered]@{
        file = $file.Name
        seed = $map['seed']
        layers = $map['layers']
        steps = $map['steps']
        batch_size = $map['batch_size']
        learning_rate = $map['learning_rate']
        status = $map['status']
    }
    $evalRows += $row
}

$cpuAnchorRows = @()
$selectionPath = Join-Path $pilot "checkpoint-selection.csv"
if (Test-Path -LiteralPath $selectionPath) {
    $csv = Import-Csv -LiteralPath $selectionPath
    foreach ($r in $csv) {
        if ($r.seed -eq "1" -and $r.layers -eq "19") {
            $cpuAnchorRows += [ordered]@{
                seed = $r.seed
                layers = $r.layers
                selected_step = $r.selected_step
                selected_validation_nll = $r.selected_validation_nll
                source = "cpu-anchor"
            }
        }
    }
}

if (Test-Path -LiteralPath $output) {
    Remove-Item -LiteralPath $output -Recurse -Force
}
[IO.Directory]::CreateDirectory($output) | Out-Null

Write-Csv (Join-Path $output "generation-summary.csv") $summaryRows
Write-Csv (Join-Path $output "generation-parity.csv") $parityRows
Write-Csv (Join-Path $output "generation-ar.csv") $arRows
Write-Csv (Join-Path $output "training-status.csv") $evalRows
Write-Csv (Join-Path $output "cpu-anchor.csv") $cpuAnchorRows

$limitations = @(
    [ordered]@{ item = "HTP step-1000 generation"; status = "BLOCKED by parity gate"; note = "CPU/HTP logit absolute error exceeds the fixed 2e-2 gate after 1000 steps; CPU-generated step-1000 text is provided for quality comparison." },
    [ordered]@{ item = "raw bytes"; status = "EXCLUDED"; note = "Only aggregate byte/UTF-8 statistics are published; generated text is not included." }
)
Write-Csv (Join-Path $output "limitations.csv") $limitations

$allowList = @(
    "README.md","manifest.json",
    "generation-summary.csv","generation-parity.csv","generation-ar.csv",
    "training-status.csv","cpu-anchor.csv","limitations.csv"
)
$manifestedFiles = @($allowList | Where-Object { $_ -ne "manifest.json" })
$manifest = [ordered]@{
    source_commit = if ($SourceCommit) { $SourceCommit } else { $null }
    created = (Get-Date -Format "yyyy-MM-ddTHH:mm:ssZ")
    files = [ordered]@{}
}
foreach ($name in $manifestedFiles) {
    $path = Join-Path $output $name
    if (Test-Path -LiteralPath $path) {
        $manifest.files[$name] = [ordered]@{
            sha256 = (Get-NormalizedSha256 $path)
            bytes = (Get-Item -LiteralPath $path).Length
        }
    }
}
Write-Json (Join-Path $output "manifest.json") $manifest

[IO.File]::WriteAllText((Join-Path $output "README.md"), @'
# Nicopedia HTP step-320 vs step-1000 comparison

This bundle contains aggregate results comparing the L19 seed-1 checkpoint at
step 320 and step 1000 trained on the Nicopedia real-text corpus with QNN HTP.

## Teacher-forced metrics (allow-listed aggregates)

| checkpoint | source | validation NLL | selected step |
|------------|--------|---------------|---------------|
| L19 seed-1 step-1000 | CPU anchor | 2.510798771 | 1000 |
| L19 seed-1 step-1000 | HTP | 2.553278928 | 1000 |

The HTP step-1000 validation NLL is within ~0.04 of the CPU anchor.

## Generation status

- Step-320 HTP generation (published successful runs): SUCCESS, parity and AR gates PASS.
- Step-1000 HTP generation: BLOCKED by CPU/HTP parity gate.
  The fixed 2e-2 absolute logit-error gate is exceeded because logits grow in
  magnitude between step 320 and step 1000 (CPU logit RMS ~3.21 -> ~3.57 for
  prefix 0). Cosine similarity remains above 0.999998, argmax agreement is
  preserved, and top-k set overlap stays 5/5, so the ranking topology is intact.
- Step-1000 CPU generation is available privately for quality comparison;
  only aggregate byte/UTF-8 statistics are published here.

## Files

- generation-summary.csv: aggregate generation statistics per run.
- generation-parity.csv: CPU/HTP parity error magnitudes per prefix.
- generation-ar.csv: CPU/HTP autoregressive parity error magnitudes per step.
- training-status.csv: training run metadata.
- cpu-anchor.csv: CPU-selected anchor NLL from the public pilot bundle.
- limitations.csv: known limitations and blocked outputs.
- manifest.json: content hashes for the other published files (the manifest
  deliberately excludes its own self-referential hash).

The CSVs are a fixed historical canonical aggregate. The exporter refuses to
replace this bundle unless its input contains the canonical L19 seed-1
step-320 greedy/max-64 success with all unchanged generation gates passing;
mutable parity-control reports are not substituted for that source.

## Reproduction (manual)

```powershell
# Training
scripts/run_nicopedia_htp_training.ps1 -Layers 19 -Seed 1 -Steps 1000 `
  -QairtSdkRoot "C:\Qualcomm\AIStack\QAIRT\2.48.40.260702" `
  -ExpectedBuildId "2.48.40.260702151143"

# Generation (step 320)
scripts/run_nicopedia_htp_generate.ps1 -Model L19 -Seed 1 `
  -PromptFile <private-greedy-prompt-file> -MaxNewBytes 64 -Mode Greedy -CheckpointStep 320 `
  -QairtSdkRoot "C:\Qualcomm\AIStack\QAIRT\2.48.40.260702" `
  -ExpectedBuildId "2.48.40.260702151143"

# Host eval
build/host_tests/htp_checkpoint_eval.exe `
  build/reports/nicopedia-htp-training/htp-seed1-l19-step1000.ckpt `
  build/private-data/nicopedia-real-text/caches/validation.bin `
  build/private-data/nicopedia-real-text/caches/development.bin 256 512
```
'@ + "`n", [Text.UTF8Encoding]::new($false))

# Re-create manifest after README is written.
$manifest.files = [ordered]@{}
foreach ($name in $manifestedFiles) {
    $path = Join-Path $output $name
    if (Test-Path -LiteralPath $path) {
        $manifest.files[$name] = [ordered]@{
            sha256 = (Get-NormalizedSha256 $path)
            bytes = (Get-Item -LiteralPath $path).Length
        }
    }
}
Write-Json (Join-Path $output "manifest.json") $manifest

if ($SelfTest) {
    # Leak guard: no raw bytes or fingerprints must appear in the published CSVs.
    $published = Get-ChildItem -LiteralPath $output -File | Where-Object { $_.Extension -eq '.csv' }
    foreach ($csv in $published) {
        $text = Get-Content -LiteralPath $csv.FullName -Raw
        if ($text -match '\b[0-9a-f]{64}\b' -or $text -match 'fnv1a64:' -or $text -match '[0-9a-f]{128,}') {
            throw "Leak guard failed in $($csv.Name): content fingerprint found"
        }
        if ($text -match 'device_serial|adb|com\.yuubinnkyoku') {
            throw "Leak guard failed in $($csv.Name): device/host identifier found"
        }
    }
    # Allow-list guard: every file in the output directory must be in the manifest.
    $actual = Get-ChildItem -LiteralPath $output -File | Select-Object -ExpandProperty Name | Sort-Object
    $expected = $allowList | Sort-Object
    if (Compare-Object $actual $expected) {
        throw "Allow-list guard failed: output files [$($actual -join ', ')] differ from expected [$($expected -join ', ')]"
    }
    $manifestMap = Get-Content -Raw -LiteralPath (Join-Path $output "manifest.json") |
        ConvertFrom-Json -AsHashtable
    $manifestNames = @($manifestMap.files.Keys | Sort-Object)
    $expectedManifestNames = @($manifestedFiles | Sort-Object)
    if (Compare-Object $manifestNames $expectedManifestNames) {
        throw "Manifest guard failed: entries [$($manifestNames -join ', ')] differ from expected [$($expectedManifestNames -join ', ')]"
    }
    foreach ($name in $manifestedFiles) {
        $path = Join-Path $output $name
        if ($manifestMap.files[$name].sha256 -ne (Get-NormalizedSha256 $path) -or
            [long]$manifestMap.files[$name].bytes -ne (Get-Item -LiteralPath $path).Length) {
            throw "Manifest guard failed: stale hash or byte count for $name"
        }
    }
    $summary = @(Import-Csv -LiteralPath (Join-Path $output "generation-summary.csv"))
    $step320 = @($summary | Where-Object { $_.checkpoint_step -eq '320' })
    $step1000 = @($summary | Where-Object { $_.checkpoint_step -eq '1000' })
    if ($step320.Count -ne 1 -or $step320[0].status -ne 'SUCCESS' -or
        $step320[0].generate_mode -ne 'greedy' -or $step320[0].max_new_bytes -ne '64' -or
        $step320[0].parity_gate -ne 'true' -or $step320[0].ar_gate -ne 'true' -or
        $step320[0].generation_gate -ne 'true' -or [int]$step320[0].generated_byte_count -ne 64) {
        throw "Publication semantics guard failed: step-320 control rejection was not excluded"
    }
    if ($step1000.Count -ne 0) {
        throw "Publication semantics guard failed: blocked step-1000 run entered the historical generation rows"
    }
    $readmeText = Get-Content -Raw -LiteralPath (Join-Path $output "README.md")
    if ($readmeText -notmatch 'published successful runs.*SUCCESS, parity and AR gates PASS' -or
        $readmeText -notmatch 'Step-1000 HTP generation: BLOCKED by CPU/HTP parity gate') {
        throw "Publication semantics guard failed: README status summary is inconsistent"
    }
    Write-Host "qnn_nicopedia_htp_1000step_generation_exporter_self_test=PASS"
}

Write-Host "qnn_nicopedia_htp_1000step_generation_exporter=PASS output=$output"
